║     Server Started Successfully        ║
╠════════════════════════════════════════╣
║ Port:       ${PORT.toString().padEnd(33)}║
║ Environment: ${NODE_ENV.padEnd(32)}║
║ CORS Origins: ${ALLOWED_ORIGINS[0].padEnd(30)}║
╚════════════════════════════════════════╝
  `);
});

// Graceful shutdown
