// Secure Express application with security best practices implemented
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { query, validationResult } = require('express-validator');

const app = express();

// ============= SECURITY MIDDLEWARE =============

// 1. Security Headers
app.use(helmet());

// 2. Logging
app.use(morgan('combined'));

// 3. CORS Configuration
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 4. Body Parser with Size Limits
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// 5. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ============= AUTHENTICATION MIDDLEWARE =============

// Simple JWT validation (replace with your auth method)
const authenticateRequest = (req, res, next) => {
  const token = req.headers.authorization?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({ 
      error: 'Unauthorized',
      message: 'Authorization header required'
    });
  }

  // Add basic token validation
  // In production, verify JWT signature and expiration
  if (!token.startsWith('sk-test-') && !token.startsWith('sk-live-')) {
    return res.status(403).json({ 
      error: 'Forbidden',
      message: 'Invalid token format'
    });
  }

  req.user = { authenticated: true };
  next();
};

// ============= ROUTES =============

// Health check (no auth required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Protected users endpoint with input validation
app.get('/users', 
  authenticateRequest,
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    // Return sanitized user data (removed email from public response)
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    res.json({
      data: users.slice(offset, offset + limit),
      pagination: {
        limit,
        offset,
        total: users.length
      }
    });
  }
);

// ============= ERROR HANDLING =============

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found', path: req.path });
});

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal error details to clients
  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: err.message || 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============= SERVER STARTUP =============

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV'];
requiredEnvVars.forEach(varName => {
  if (varName !== 'NODE_ENV' && !process.env[varName]) {
    console.warn(`Warning: Environment variable ${varName} is not set`);
  }
});

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Only use HTTP in development
if (process.env.NODE_ENV === 'production') {
  console.warn('⚠️  HTTPS/TLS must be configured in production');
}

app.listen(PORT, HOST, () => {
  console.log(`✓ Server running on ${HOST}:${PORT}`);
  console.log(`✓ Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`✓ Security headers enabled`);
});

module.exports = app;

// Security Test Examples for Express Application
// These tests verify that security controls are properly implemented

const request = require('supertest');
const app = require('./app.secure'); // Use the secured version

describe('Security Tests', () => {

  // ============= AUTHENTICATION TESTS =============

  describe('Authentication', () => {

    test('should reject requests without authorization header', async () => {
      const response = await request(app)
        .get('/users')
        .expect(401);

      expect(response.body.error).toBe('Unauthorized');
    });

    test('should reject requests with invalid token format', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer invalid_token')
        .expect(403);

      expect(response.body.error).toBe('Forbidden');
    });

    test('should accept requests with valid token', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer sk-test-valid')
        .expect(200);

      expect(response.body.data).toBeDefined();
    });

    test('health endpoint should not require authentication', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.body.status).toBe('ok');
    });
  });

  // ============= INPUT VALIDATION TESTS =============

  describe('Input Validation', () => {

    const validToken = 'Bearer sk-test-valid';

    test('should reject invalid limit parameter', async () => {
      const response = await request(app)
        .get('/users?limit=999') // Exceeds max of 100
        .set('Authorization', validToken)
        .expect(400);

      expect(response.body.errors).toBeDefined();
    });

    test('should reject negative offset parameter', async () => {
      const response = await request(app)
        .get('/users?offset=-1')
        .set('Authorization', validToken)
        .expect(400);

      expect(response.body.errors).toBeDefined();
    });

    test('should accept valid pagination parameters', async () => {
      const response = await request(app)
        .get('/users?limit=10&offset=0')
        .set('Authorization', validToken)
        .expect(200);

      expect(response.body.pagination.limit).toBe(10);
      expect(response.body.pagination.offset).toBe(0);
    });

    test('should sanitize output - no email in public response', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', validToken)
        .expect(200);

      response.body.data.forEach(user => {
        expect(user.email).toBeUndefined();
        expect(user.id).toBeDefined();
        expect(user.name).toBeDefined();
      });
    });
  });

  // ============= SECURITY HEADERS TESTS =============

  describe('Security Headers', () => {

    test('should include X-Content-Type-Options header', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    test('should include X-Frame-Options header', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['x-frame-options']).toBe('DENY');
    });

    test('should include Strict-Transport-Security header in production', async () => {
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['strict-transport-security']).toBeDefined();

      process.env.NODE_ENV = 'test';
    });

    test('should include Content-Security-Policy header', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['content-security-policy']).toBeDefined();
    });

    test('should not expose server information', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      // Helmet should remove the X-Powered-By header
      expect(response.headers['x-powered-by']).toBeUndefined();
    });
  });

  // ============= CORS TESTS =============

  describe('CORS Policy', () => {

    test('should accept requests from allowed origin', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000')
        .expect(200);

      expect(response.headers['access-control-allow-origin']).toBeDefined();
    });

    test('should reject requests from disallowed origin', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://malicious-site.com')
        .expect(200); // The request succeeds but CORS headers may differ

      // CORS rejection happens at browser level, but we can verify headers
      // This depends on your CORS configuration
    });

    test('should restrict HTTP methods', async () => {
      const response = await request(app)
        .delete('/users')
        .expect(404); // Should not support DELETE
    });
  });

  // ============= RATE LIMITING TESTS =============

  describe('Rate Limiting', () => {

    test('should allow requests within rate limit', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['ratelimit-limit']).toBeDefined();
      expect(response.headers['ratelimit-remaining']).toBeDefined();
    });

    test('should return 429 after exceeding rate limit', async () => {
      // Make 101 requests (limit is 100)
      let response;
      for (let i = 0; i < 101; i++) {
        response = await request(app)
          .get('/health');
      }

      expect(response.status).toBe(429);
      expect(response.body.message).toContain('Too many requests');
    });

    test('rate limit headers should be present', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['ratelimit-limit']).toBe('100');
      expect(parseInt(response.headers['ratelimit-remaining'])).toBeLessThanOrEqual(100);
      expect(response.headers['ratelimit-reset']).toBeDefined();
    });
  });

  // ============= ERROR HANDLING TESTS =============

  describe('Error Handling', () => {

    test('should return 404 for undefined routes', async () => {
      const response = await request(app)
        .get('/undefined-route')
        .expect(404);

      expect(response.body.error).toBe('Not Found');
    });

    test('should not expose stack traces in production', async () => {
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/undefined-route')
        .expect(404);

      expect(response.body.stack).toBeUndefined();

      process.env.NODE_ENV = 'test';
    });

    test('should expose stack traces in development', async () => {
      process.env.NODE_ENV = 'development';

      const response = await request(app)
        .get('/undefined-route')
        .expect(404);

      expect(response.body.stack).toBeDefined();

      process.env.NODE_ENV = 'test';
    });

    test('should return proper Content-Type for error responses', async () => {
      const response = await request(app)
        .get('/undefined-route')
        .expect(404);

      expect(response.headers['content-type']).toContain('application/json');
    });
  });

  // ============= DATA SANITIZATION TESTS =============

  describe('Data Sanitization', () => {

    test('should not return sensitive fields', async () => {
