const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';

// Determine environment type
const isDevelopment = NODE_ENV === 'development';
const isProduction = NODE_ENV === 'production';
const isTest = NODE_ENV === 'test';

// ============= ENVIRONMENT-SPECIFIC SETUP =============

// Development mode: Enable verbose logging and debugging
if (isDevelopment) {
  console.log('📍 Running in DEVELOPMENT mode');

  // Add request logging in development
  app.use((req, res, next) => {
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
    next();
  });
}

// Production mode: Optimize for performance and security
else if (isProduction) {
  console.log('📍 Running in PRODUCTION mode');

  // Trust proxy headers (important for cloud deployments)
  app.set('trust proxy', 1);

  // Disable x-powered-by header
  app.disable('x-powered-by');
}

// ============= ROUTES =============

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ============= ERROR HANDLING =============

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // In development, show full error details
  if (isDevelopment) {
    res.status(err.status || 500).json({
      error: err.message,
      stack: err.stack
    });
  } 
  // In production, hide error details
  else {
    res.status(err.status || 500).json({
      error: 'Internal Server Error'
    });
  }
});

// ============= CONFIGURATION VALIDATION =============

// Validate required environment variables
function validateConfiguration() {
  const requiredVars = [];

  // Add validation for critical environment variables
  // Example: if (isProduction && !process.env.DATABASE_URL) {
  //   requiredVars.push('DATABASE_URL');
  // }

  if (requiredVars.length > 0) {
    console.error('❌ Missing required environment variables:');
    requiredVars.forEach(v => console.error(`   - ${v}`));
    process.exit(1);
  }

  console.log('✅ Configuration validated');
}

// ============= SERVER STARTUP =============

// Validate configuration before starting server
validateConfiguration();

// Start the server
const server = app.listen(PORT, HOST, () => {
  console.log(`
