// Secure version of the application with security best practices implemented

require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');

const app = express();

// ============================================================================
// Environment Configuration
// ============================================================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;

// Validate required environment variables in production
if (NODE_ENV === 'production') {
  if (!JWT_SECRET) {
    throw new Error('JWT_SECRET environment variable is required in production');
  }
}

// ============================================================================
// Security Middleware
// ============================================================================

// 1. Helmet - Set various HTTP headers for security
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
  },
}));

// 2. CORS - Control cross-origin requests
const allowedOrigins = process.env.ALLOWED_ORIGINS 
  ? process.env.ALLOWED_ORIGINS.split(',') 
  : ['http://localhost:3000'];

app.use(cors({
  origin: allowedOrigins,
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// 3. HTTPS Enforcement in production
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// 4. Logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// 5. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // strict limit for auth endpoints
  skipSuccessfulRequests: true,
});

app.use(limiter);

// ============================================================================
// Body Parsing Middleware
// ============================================================================
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// Authentication Middleware
// ============================================================================
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Access token required',
      code: 'AUTH_MISSING_TOKEN' 
    });
  }

  jwt.verify(token, JWT_SECRET || 'dev-secret', (err, user) => {
    if (err) {
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        code: 'AUTH_INVALID_TOKEN' 
      });
    }
    req.user = user;
    next();
  });
}

// ============================================================================
// Routes
// ============================================================================

// Health check - public endpoint (rate limited)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
  });
});

// Get users - protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // In production, this would query a database
  // NEVER expose sensitive user data
  res.json({
    users: [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ],
    timestamp: new Date().toISOString(),
  });
});

// Authentication endpoint - generate JWT token
app.post('/auth/login', authLimiter, (req, res) => {
  // This is a simple example - use proper authentication in production
  // (e.g., bcrypt for password hashing, database lookups, etc.)

  const username = req.body.username;

  if (!username) {
    return res.status(400).json({ 
      error: 'Username is required',
      code: 'VALIDATION_ERROR' 
    });
  }

  // In production: verify credentials against database
  if (username === 'demo') {
    const user = { id: 1, username: username };
    const token = jwt.sign(user, JWT_SECRET || 'dev-secret', { expiresIn: '1h' });

    return res.json({ 
      token: token,
      expiresIn: '1h',
    });
  }

  res.status(401).json({ 
    error: 'Invalid credentials',
    code: 'AUTH_FAILED' 
  });
});

// ============================================================================
// Error Handling Middleware
// ============================================================================

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    code: 'NOT_FOUND',
    path: req.originalUrl,
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled Error:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
  });

  // Don't expose stack trace in production
  const isDevelopment = NODE_ENV === 'development';

  const response = {
    error: isDevelopment ? err.message : 'Internal Server Error',
    code: 'INTERNAL_SERVER_ERROR',
    timestamp: new Date().toISOString(),
  };

  if (isDevelopment && err.stack) {
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});

// ============================================================================
// Server Startup
// ============================================================================
const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

// Catch uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

# Security Quick Reference Guide

## 🚨 Critical Issues Summary

| Issue | Status | Priority | Action |
|-------|--------|----------|--------|
| Exposed credentials in .env.test | ⚠️ CRITICAL | IMMEDIATE | Delete file, rotate all keys |
| No environment variable management | 🔴 HIGH | THIS WEEK | Add dotenv, use .env |
| Missing security headers | 🔴 HIGH | THIS WEEK | Install helmet |
| Unprotected endpoints | 🔴 HIGH | THIS WEEK | Add authentication |
| No input validation | 🟡 MEDIUM | NEXT WEEK | Add express-validator |
| No error handling | 🟡 MEDIUM | NEXT WEEK | Add error middleware |
| No HTTPS enforcement | 🟡 MEDIUM | NEXT WEEK | Configure HTTPS |
| Missing logging | 🔵 LOW | ONGOING | Add morgan |

