## Recommended Secure app.js

Here's the refactored version with all hardcoded values externalized:

```javascript
// Load environment variables
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');

const app = express();

// ============================================================================
// ENVIRONMENT VARIABLES
// ============================================================================

// Server Configuration
const PORT = parseInt(process.env.PORT || '3000', 10);
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';
const IS_PRODUCTION = NODE_ENV === 'production';

// Validation Configuration
const MAX_JSON_SIZE = process.env.MAX_JSON_SIZE || '10kb';
const REQUEST_TIMEOUT = parseInt(process.env.REQUEST_TIMEOUT || '30000', 10);

// Security Configuration
const JWT_SECRET = process.env.JWT_SECRET;
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || [
  'http://localhost:3000',
  'http://localhost:3001'
];
const CORS_CREDENTIALS = process.env.CORS_CREDENTIALS === 'true';

// Rate Limiting Configuration
const RATE_LIMIT_WINDOW = parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10);
const RATE_LIMIT_MAX = parseInt(process.env.RATE_LIMIT_MAX || '100', 10);

// Logging Configuration
const LOG_LEVEL = process.env.LOG_LEVEL || 'combined';

// Demo Data Configuration
const DEMO_USERS = process.env.DEMO_USERS 
  ? JSON.parse(process.env.DEMO_USERS) 
  : [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

// ============================================================================
// ENVIRONMENT VALIDATION
// ============================================================================

if (IS_PRODUCTION) {
  if (!JWT_SECRET) {
    console.error('ERROR: JWT_SECRET environment variable is required in production');
    process.exit(1);
  }
}

// ============================================================================
// MIDDLEWARE
// ============================================================================

// Security Headers
app.use(helmet());

// CORS
app.use(cors({
  origin: ALLOWED_ORIGINS,
  credentials: CORS_CREDENTIALS,
  optionsSuccessStatus: 200
}));

// Request Parsing
app.use(express.json({ limit: MAX_JSON_SIZE }));
app.use(express.urlencoded({ limit: MAX_JSON_SIZE, extended: false }));

// Logging
app.use(morgan(LOG_LEVEL));

// Rate Limiting
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW,
  max: RATE_LIMIT_MAX,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// Request Timeout
app.use((req, res, next) => {
  req.setTimeout(REQUEST_TIMEOUT);
  next();
});

// ============================================================================
// ROUTES
// ============================================================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

app.get('/users', (req, res) => {
  res.json(DEMO_USERS);
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  res.status(err.status || 500).json({
    error: IS_PRODUCTION ? 'Internal Server Error' : err.message
  });
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} (${NODE_ENV})`);
});

// Graceful Shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;
```

