# 3. Verify it's gone
git log --all -- .env.test
git log --all | grep -i "CANARY"

# 4. Force push (this rewrites history)
git push origin --force-with-lease

# 5. CRITICAL: Rotate all credentials
# For each service:
# - AWS: Disable key, create new key
# - Database: Change password
# - API keys: Regenerate all
# - Stripe: Roll API keys
# - Logfire: Create new token
```

### Long-term Prevention

```javascript
// config/secrets.js
const requiredSecrets = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

// Validate on startup
function validateSecrets() {
  const missing = requiredSecrets.filter(secret => !process.env[secret]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }

  // In development, warn if using placeholder values
  if (process.env.NODE_ENV !== 'production') {
    requiredSecrets.forEach(secret => {
      if (process.env[secret]?.includes('CANARY') || 
          process.env[secret]?.includes('your_')) {
        console.warn(`⚠️  Warning: ${secret} appears to be a placeholder`);
      }
    });
  }
}
```

