  console.warn('⚠️  CORS: Allowing all origins (development mode only)');
}

app.use(cors(corsOptions));

// 3. Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => NODE_ENV === 'development', // Skip rate limiting in development
});

app.use(limiter);

// Stricter limits for sensitive operations
const strictLimiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 5,
  message: 'Too many attempts, please try again later.',
});

// ============================================
// ROUTES
// ============================================

/**
 * GET /health
 * Health check endpoint - useful for load balancers and monitoring
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

/**
 * GET /users
 * Get list of users with optional filtering
 * Query parameters: limit (max 100), offset (default 0)
 */
app.get('/users', [
