    res.status(500).json({
      error: process.env.NODE_ENV === 'production'
        ? 'Internal server error'
        : error.message,
    });
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * 404 handler - must come after all other routes
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
  });
});

/**
 * Global error handler - must come after all routes and other middleware
 * @param {Error} err - The error object
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function
 */
app.use((err, req, res, next) => {
  const statusCode = err.status || err.statusCode || 500;

  // Log the error
  console.error({
    timestamp: new Date().toISOString(),
    statusCode,
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    // Don't log sensitive data in production
    ...(NODE_ENV === 'development' && { stack: err.stack }),
  });

  // Don't expose stack traces or sensitive info in production
  const errorResponse = {
    error: NODE_ENV === 'production'
      ? 'Internal Server Error'
      : err.message,
    status: statusCode,
    ...(NODE_ENV === 'development' && {
      stack: err.stack,
      details: err.details,
    }),
  };

  res.status(statusCode).json(errorResponse);
});

// ============================================
// SERVER STARTUP
// ============================================

const server = app.listen(PORT, '0.0.0.0', () => {
  console.log(`
╔════════════════════════════════════════╗
║   Server started successfully          ║
╠════════════════════════════════════════╣
║ Port:        ${PORT.toString().padEnd(28)}║
║ Environment: ${NODE_ENV.padEnd(28)}║
║ CORS Origin: ${corsOptions.origin.toString().substring(0, 25).padEnd(28)}║
╚════════════════════════════════════════╝
  `);
});

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('\n📴 Shutting down gracefully...');
  server.close(() => {
    console.log('✅ Server closed');
    process.exit(0);
  });

  // Force shutdown after 30 seconds
  setTimeout(() => {
    console.error('❌ Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 30000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown();
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown();
});

module.exports = app;

# Node.js/Express Security Vulnerabilities Reference

## Common Node.js and Express Vulnerabilities

This reference document covers the most common security vulnerabilities found in Node.js applications and how to prevent them.

---

## 1. SQL Injection

### Vulnerability Description
Attackers inject malicious SQL code through user inputs to manipulate database queries.

### ❌ Vulnerable Code
```javascript
app.get('/user/:id', (req, res) => {
  // VULNERABLE: Directly concatenating user input
  const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
  db.query(query, (err, result) => {
    res.json(result);
  });
});

// Attack: GET /user/1 OR 1=1
// Becomes: SELECT * FROM users WHERE id = 1 OR 1=1
// Returns ALL users!
```

### ✅ Secure Code
```javascript
const { param, validationResult } = require('express-validator');

app.get('/user/:id', [
  param('id').isInt().toInt(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

  // Use parameterized queries (prepared statements)
  const query = 'SELECT * FROM users WHERE id = $1';
  db.query(query, [req.params.id], (err, result) => {
    res.json(result);
  });
});
```

---

## 2. NoSQL Injection

### Vulnerability Description
Similar to SQL injection but targets NoSQL databases like MongoDB.

### ❌ Vulnerable Code
```javascript
// VULNERABLE: Using user input directly in query
app.get('/user/:email', (req, res) => {
  User.findOne({ email: req.query.email }, (err, user) => {
    res.json(user);
  });
});

// Attack: GET /user?email={"$ne": null}
// Becomes: { email: { $ne: null } } - returns ALL users!
```

### ✅ Secure Code
```javascript
const { query, validationResult } = require('express-validator');

app.get('/user/:email', [
  query('email').isEmail().normalizeEmail(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

  User.findOne({ email: req.query.email }, (err, user) => {
    res.json(user);
  });
});
```

---

## 3. Cross-Site Scripting (XSS)

### Vulnerability Description
Attackers inject JavaScript code that executes in users' browsers.

### ❌ Vulnerable Code
```javascript
app.get('/comment/:id', (req, res) => {
  const comment = Comment.findById(req.params.id);
  // VULNERABLE: Directly rendering user input without escaping
  res.send(`<h1>${comment.text}</h1>`);
});

// Attack: Comment contains: <img src=x onerror="alert('XSS')">
// Gets executed in every user's browser!
```

### ✅ Secure Code
```javascript
const xss = require('xss');
const sanitize = require('sanitize-html');

app.get('/comment/:id', (req, res) => {
  const comment = Comment.findById(req.params.id);
  // Escape HTML entities
  const safe = xss(comment.text);
  res.send(`<h1>${safe}</h1>`);
});

// Or sanitize HTML
const clean = sanitize(comment.text, {
  allowedTags: ['b', 'i', 'em', 'strong'],
  allowedAttributes: {},
});
res.send(`<h1>${clean}</h1>`);
```

---

## 4. Cross-Site Request Forgery (CSRF)

### Vulnerability Description
Attackers trick users into making unintended requests to vulnerable sites.

### ❌ Vulnerable Code
```javascript
// VULNERABLE: No CSRF protection
app.post('/transfer-money', (req, res) => {
  const { amount, recipient } = req.body;
  transfer(amount, recipient);
  res.json({ success: true });
});

// Attack: Malicious site contains:
// <img src="https://yourbank.com/transfer-money?amount=1000&recipient=attacker">
// User's browser sends authenticated request!
```

### ✅ Secure Code
```javascript
const csrf = require('csurf');
const cookieParser = require('cookie-parser');
const session = require('express-session');

app.use(cookieParser());
app.use(session({ secret: process.env.SESSION_SECRET }));

const csrfProtection = csrf({ cookie: false });

app.get('/transfer', csrfProtection, (req, res) => {
  res.render('transfer', { csrfToken: req.csrfToken() });
});

app.post('/transfer-money', csrfProtection, (req, res) => {
  // CSRF token is validated automatically
  const { amount, recipient } = req.body;
  transfer(amount, recipient);
  res.json({ success: true });
});

// HTML form must include:
// <form method="POST" action="/transfer-money">
//   <input type="hidden" name="_csrf" value="<%= csrfToken %>">
//   ...
// </form>
```

---

## 5. Insecure Deserialization

### Vulnerability Description
Untrusted data is deserialized without validation, allowing code execution.

### ❌ Vulnerable Code
```javascript
const pickle = require('pickle'); // Python's pickle-like library

app.post('/data', (req, res) => {
  // VULNERABLE: Deserializing untrusted data
  const data = pickle.loads(req.body.data);
  res.json(data);
});

// Attack: Serialized payload executes arbitrary code
```

### ✅ Secure Code
```javascript
const { body, validationResult } = require('express-validator');

app.post('/data', [
  body('data').isJSON(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

  // Parse and validate JSON instead
  try {
    const data = JSON.parse(req.body.data);
    // Validate structure
    if (!data.id || !data.name) {
      return res.status(400).json({ error: 'Invalid data structure' });
    }
    res.json(data);
  } catch (e) {
    res.status(400).json({ error: 'Invalid JSON' });
  }
});

// Use JSON schema validation for complex data
const Ajv = require('ajv');
const ajv = new Ajv();

const schema = {
  type: 'object',
  properties: {
    id: { type: 'integer' },
    name: { type: 'string' },
  },
  required: ['id', 'name'],
};

const validate = ajv.compile(schema);
if (!validate(data)) {
  return res.status(400).json({ error: 'Invalid data', details: validate.errors });
}
```

