## 6. Broken Authentication

### Vulnerability Description
Weak password policies, session management, or credential handling.

### ❌ Vulnerable Code
```javascript
// VULNERABLE: Storing passwords in plain text
app.post('/register', (req, res) => {
  const user = new User({
    email: req.body.email,
    password: req.body.password, // Plain text!
  });
  user.save();
  res.json({ success: true });
});

// VULNERABLE: Weak password validation
app.post('/login', (req, res) => {
  const user = User.findOne({ email: req.body.email });
  if (user.password === req.body.password) { // Direct comparison!
    req.session.userId = user.id;
    res.json({ token: user.id }); // Weak token!
  }
});
```

### ✅ Secure Code
```javascript
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');

// Registration
app.post('/register', [
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 12 }).matches(/[A-Z]/).matches(/[0-9]/),
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

  const hashedPassword = await bcrypt.hash(req.body.password, 12);
  const user = new User({
    email: req.body.email,
    password: hashedPassword,
  });
  await user.save();
  res.json({ success: true });
});

// Login
app.post('/login', [
  body('email').isEmail().normalizeEmail(),
  body('password').exists(),
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

  const user = await User.findOne({ email: req.body.email });
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  const validPassword = await bcrypt.compare(req.body.password, user.password);
  if (!validPassword) return res.status(401).json({ error: 'Invalid credentials' });

  const token = jwt.sign(
    { userId: user.id, email: user.email },
    process.env.JWT_SECRET,
    { expiresIn: '24h' }
  );

  res.json({ token });
});

// JWT Middleware
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.userId = decoded.userId;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
};
```

