## 8. XML External Entity (XXE) Injection

### Vulnerability Description
Processing untrusted XML that contains external entity references.

### ❌ Vulnerable Code
```javascript
const xml2js = require('xml2js');

app.post('/upload-xml', (req, res) => {
  const parser = new xml2js.Parser();
  // VULNERABLE: No XXE protection
  parser.parseString(req.body, (err, result) => {
    res.json(result);
  });
});

// Attack: XML containing external entity reads local files:
// <?xml version="1.0"?>
// <!DOCTYPE foo [<!ENTITY xxe SYSTEM "file:///etc/passwd">]>
// <data>&xxe;</data>
```

### ✅ Secure Code
```javascript
const xml2js = require('xml2js');

app.post('/upload-xml', (req, res) => {
  const parser = new xml2js.Parser({
    // Disable external entity resolution
    strict: true,
    normalizeTags: true,
    // Additional security options
    maxDepth: 5, // Prevent billion laughs attack
  });

  parser.parseString(req.body, (err, result) => {
    if (err) return res.status(400).json({ error: 'Invalid XML' });
    res.json(result);
  });
});

// Or use safer XML parsing libraries like fast-xml-parser
const fastXmlParser = require('fast-xml-parser');

app.post('/upload-xml', (req, res) => {
  try {
    const result = fastXmlParser.parse(req.body, {
      ignoreAttributes: false,
      parseTagValue: false,
    });
    res.json(result);
  } catch (err) {
    res.status(400).json({ error: 'Invalid XML' });
  }
});
```

