## 9. Broken Access Control

### Vulnerability Description
Users access resources or perform actions they shouldn't be authorized for.

### ❌ Vulnerable Code
```javascript
// VULNERABLE: No authorization check
app.get('/user/:id', (req, res) => {
  const user = User.findById(req.params.id);
  res.json(user); // Anyone can view any user!
});

// VULNERABLE: Authorization based on user input
app.get('/user/:id', (req, res) => {
  if (req.query.admin === 'true') { // User can set this!
    res.json(User.findById(req.params.id));
  }
});
```

### ✅ Secure Code
```javascript
// Middleware to check authorization
const requireAuth = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.userId = decoded.userId;
    req.isAdmin = decoded.isAdmin;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
};

// SECURE: Check ownership
app.get('/user/:id', requireAuth, (req, res) => {
  const userId = parseInt(req.params.id);

  // User can only view their own profile (unless admin)
  if (req.userId !== userId && !req.isAdmin) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const user = User.findById(userId);
  res.json(user);
});

// SECURE: Admin-only endpoint
app.delete('/user/:id', requireAuth, (req, res) => {
  if (!req.isAdmin) {
    return res.status(403).json({ error: 'Admin access required' });
  }

  User.deleteOne({ id: req.params.id });
  res.json({ success: true });
});

// Role-based access control (RBAC)
const requireRole = (...allowedRoles) => {
  return (req, res, next) => {
    if (!allowedRoles.includes(req.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

app.post('/admin/users', requireAuth, requireRole('admin'), (req, res) => {
  // Only admins can create users
});
```

