// config.js - Centralized Configuration Management
// This file loads and validates all environment variables

require('dotenv').config();

const config = {
  // ============================================
  // SERVER CONFIGURATION
  // ============================================
  nodeEnv: process.env.NODE_ENV || 'development',
  port: parseInt(process.env.PORT || 3000),
  host: process.env.HOST || 'localhost',
  isDevelopment: (process.env.NODE_ENV || 'development') === 'development',
  isProduction: process.env.NODE_ENV === 'production',
  isStaging: process.env.NODE_ENV === 'staging',

  // ============================================
  // CORS CONFIGURATION
  // ============================================
  cors: {
    origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    credentials: process.env.CORS_ALLOW_CREDENTIALS !== 'false',
    maxAge: parseInt(process.env.CORS_MAX_AGE || 86400),
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    optionsSuccessStatus: 200,
  },

  // ============================================
  // RATE LIMITING
  // ============================================
  rateLimiting: {
    enabled: process.env.ENABLE_RATE_LIMITING !== 'false',
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || 15 * 60 * 1000), // 15 min
    max: parseInt(process.env.RATE_LIMIT_MAX || 100),
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
    skipInDevelopment: true,
  },

  // ============================================
  // STRICT RATE LIMITING (for sensitive endpoints)
  // ============================================
  strictLimiting: {
    windowMs: parseInt(process.env.STRICT_LIMIT_WINDOW_MS || 1 * 60 * 1000), // 1 min
    max: parseInt(process.env.STRICT_LIMIT_MAX || 5),
    message: 'Too many attempts, please try again later.',
  },

  // ============================================
  // SECURITY HEADERS (HSTS)
  // ============================================
  hsts: {
    maxAge: parseInt(process.env.HSTS_MAX_AGE || 31536000), // 1 year
    includeSubDomains: process.env.HSTS_INCLUDE_SUBDOMAINS !== 'false',
    preload: process.env.HSTS_PRELOAD !== 'false',
  },

  // ============================================
  // API CONFIGURATION
  // ============================================
  api: {
    maxPageSize: parseInt(process.env.MAX_PAGE_SIZE || 100),
    defaultPageSize: parseInt(process.env.DEFAULT_PAGE_SIZE || 10),
  },

  // ============================================
  // PAYLOAD SIZE LIMITS
  // ============================================
  payloads: {
    jsonLimit: process.env.JSON_LIMIT || '10kb',
    urlEncodedLimit: process.env.URL_ENCODED_LIMIT || '10kb',
  },

  // ============================================
  // GRACEFUL SHUTDOWN
  // ============================================
  gracefulShutdown: {
    timeoutMs: parseInt(process.env.SHUTDOWN_TIMEOUT_MS || 30000),
  },

  // ============================================
  // DATABASE
  // ============================================
  database: {
    url: process.env.DATABASE_URL || '',
  },

  // ============================================
  // AWS
  // ============================================
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID || '',
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || '',
    region: process.env.AWS_REGION || 'us-east-1',
  },

  // ============================================
  // THIRD-PARTY SERVICES
  // ============================================
  services: {
    stripe: {
      secretKey: process.env.STRIPE_SECRET_KEY || '',
    },
    anthropic: {
      apiKey: process.env.ANTHROPIC_API_KEY || '',
    },
    logfire: {
      token: process.env.LOGFIRE_TOKEN || '',
    },
  },

  // ============================================
  // LOGGING
  // ============================================
  logging: {
    level: process.env.LOG_LEVEL || 'info',
    file: process.env.LOG_FILE || 'combined.log',
    errorFile: process.env.LOG_ERROR_FILE || 'error.log',
  },

  // ============================================
  // MONITORING
  // ============================================
  monitoring: {
    sentryDsn: process.env.SENTRY_DSN || '',
  },

  // ============================================
  // FEATURES
  // ============================================
  features: {
    useMockData: process.env.USE_MOCK_DATA === 'true',
  },
};

// ============================================
// VALIDATION
// ============================================

/**
 * Validate required environment variables
 */
function validateConfig() {
  const errors = [];

  // Production validations
  if (config.isProduction) {
    const requiredProduction = ['DATABASE_URL', 'NODE_ENV'];
    requiredProduction.forEach(key => {
      if (!process.env[key]) {
        errors.push(`Missing required environment variable in production: ${key}`);
      }
    });

    // Check for credentials (should be from secure vault, not env vars)
    if (!config.database.url) {
      errors.push('DATABASE_URL is required in production');
    }
  }

  // Validate port is a valid number
  if (isNaN(config.port) || config.port < 1 || config.port > 65535) {
    errors.push(`Invalid PORT: ${process.env.PORT} (must be between 1-65535)`);
  }

  // Validate rate limiting values
  if (config.rateLimiting.windowMs < 1000) {
    errors.push('RATE_LIMIT_WINDOW_MS must be at least 1000ms (1 second)');
  }

  if (config.rateLimiting.max < 1) {
    errors.push('RATE_LIMIT_MAX must be at least 1');
  }

  // Validate HSTS max age
  if (config.hsts.maxAge < 0) {
    errors.push('HSTS_MAX_AGE must be a positive number');
  }

  // Validate pagination
  if (config.api.maxPageSize < 1) {
    errors.push('MAX_PAGE_SIZE must be at least 1');
  }

  if (config.api.defaultPageSize < 1 || config.api.defaultPageSize > config.api.maxPageSize) {
    errors.push('DEFAULT_PAGE_SIZE must be between 1 and MAX_PAGE_SIZE');
  }

  // Log validation errors and exit if any found
  if (errors.length > 0) {
    console.error('❌ Configuration Validation Errors:');
    errors.forEach(error => console.error(`   - ${error}`));
    if (config.isProduction) {
      process.exit(1);
    } else {
      console.warn('⚠️  Running with configuration errors (development mode)');
    }
  }
}

/**
 * Log configuration summary (without sensitive values)
 */
function logConfigSummary() {
  console.log('\n📋 Configuration Summary:');
  console.log(`   Environment: ${config.nodeEnv}`);
  console.log(`   Server: ${config.host}:${config.port}`);
  console.log(`   CORS Origins: ${config.cors.origin}`);
  console.log(`   Rate Limiting: ${config.rateLimiting.enabled ? 'enabled' : 'disabled'}`);
  if (config.rateLimiting.enabled) {
    console.log(`     - Window: ${config.rateLimiting.windowMs / 1000}s`);
    console.log(`     - Max: ${config.rateLimiting.max} requests`);
  }
  console.log(`   Database: ${config.database.url ? '✓ configured' : '✗ not configured'}`);
  console.log(`   Mock Data: ${config.features.useMockData ? 'enabled' : 'disabled'}\n`);
}

// Validate on load
validateConfig();

// Export configuration
module.exports = config;

// Export validation function for testing
module.exports.validateConfig = validateConfig;

// Export logging function
module.exports.logConfigSummary = logConfigSummary;

# Configuration Management Guide

## Overview

This document explains how to use the centralized configuration system to manage all hardcoded values and environment variables.

---

## Files Included

### 1. `config.js` - Centralized Configuration
- Loads all environment variables
- Provides defaults for missing values
- Validates configuration on startup
- Provides utility functions

### 2. `.env.example` - Configuration Template
- Lists all available configuration options
- Documents each variable
- Provides sensible defaults
- No secrets included

### 3. `.gitignore` - Git Configuration
- Prevents `.env` files from being committed
- Protects against accidental secret exposure

---

## Quick Start

### Step 1: Load Configuration in app.js

```javascript
// Before
const express = require('express');
const app = express();

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// After
const config = require('./config');
const express = require('express');
const app = express();

app.listen(config.port, config.host, () => {
  console.log(`Server running on ${config.host}:${config.port}`);
});
```

### Step 2: Use Configuration in Middleware

```javascript
// Helmet with configuration
app.use(helmet.hsts(config.hsts));

// CORS with configuration
app.use(cors(config.cors));

// Rate limiting with configuration
if (config.rateLimiting.enabled) {
  app.use(rateLimit(config.rateLimiting));
}

// Body parser with configuration
app.use(express.json({ limit: config.payloads.jsonLimit }));
app.use(express.urlencoded({ limit: config.payloads.urlEncodedLimit }));
```

### Step 3: Create .env File

```bash
cp .env.example .env
# Edit .env with your values
```

---

## Configuration Usage Examples

### Get Server Port
```javascript
const config = require('./config');
const port = config.port; // Returns: 3000 (or process.env.PORT)
```

### Check Environment
```javascript
const config = require('./config');

if (config.isProduction) {
  // Production-specific code
}

if (config.isDevelopment) {
  // Development-specific code
}

if (config.isStaging) {
  // Staging-specific code
}
```

### Use Rate Limiting Configuration
```javascript
const config = require('./config');
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: config.rateLimiting.windowMs,
  max: config.rateLimiting.max,
  message: config.rateLimiting.message,
});

app.use(limiter);
```

### Check if Feature is Enabled
```javascript
const config = require('./config');

if (config.features.useMockData) {
  // Use mock data
  const users = mockUsers;
} else {
  // Use real database
  const users = await User.find();
}
```

### Access Database URL
```javascript
const config = require('./config');

const dbUrl = config.database.url;
// Use for database connection
```

### Access AWS Credentials
```javascript
const config = require('./config');

const s3 = new AWS.S3({
  accessKeyId: config.aws.accessKeyId,
  secretAccessKey: config.aws.secretAccessKey,
  region: config.aws.region,
});
```

### Access Third-Party API Keys
```javascript
const config = require('./config');

const stripe = require('stripe')(config.services.stripe.secretKey);
```

