## Migration Guide: From Hardcoded Values

### Before (Hardcoded)
```javascript
const PORT = 3000;
const RATE_LIMIT_MAX = 100;
const HSTS_MAX_AGE = 31536000;

app.listen(PORT, () => {
  console.log(`Server on port ${PORT}`);
});

app.use(helmet.hsts({
  maxAge: HSTS_MAX_AGE,
}));

app.use(rateLimit({
  max: RATE_LIMIT_MAX,
}));
```

### After (Configured)
```javascript
const config = require('./config');

app.listen(config.port, config.host, () => {
  console.log(`Server on ${config.host}:${config.port}`);
});

app.use(helmet.hsts(config.hsts));
app.use(rateLimit(config.rateLimiting));
```

