## Complete Example: Using Config in app.js

```javascript
// app.js
require('dotenv').config();
const config = require('./config');
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers using configuration
app.use(helmet());
app.use(helmet.hsts(config.hsts));

// CORS using configuration
app.use(cors(config.cors));

// Body parser using configuration
app.use(express.json({ limit: config.payloads.jsonLimit }));
app.use(express.urlencoded({ limit: config.payloads.urlEncodedLimit }));

// Rate limiting using configuration
if (config.rateLimiting.enabled) {
  app.use(rateLimit(config.rateLimiting));
}

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', [
  query('limit')
    .optional()
    .isInt({ min: 1, max: config.api.maxPageSize })
    .withMessage(`limit must be between 1 and ${config.api.maxPageSize}`),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const limit = Math.min(
    parseInt(req.query.limit) || config.api.defaultPageSize,
    config.api.maxPageSize
  );

  // Use mock data or real database based on configuration
  const users = config.features.useMockData
    ? [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ]
    : []; // Load from database

  res.json({
    data: users.slice(0, limit),
    pagination: { limit, total: users.length },
  });
});

// ============================================
// ERROR HANDLING
// ============================================

app.use((err, req, res, next) => {
  const message = config.isDevelopment ? err.message : 'Internal Server Error';
  res.status(500).json({ error: message });
});

// ============================================
// SERVER STARTUP
// ============================================

const server = app.listen(config.port, config.host, () => {
  config.logConfigSummary();
  console.log(`✅ Server started successfully`);
});

// Graceful shutdown using configuration
const gracefulShutdown = () => {
  console.log('📴 Shutting down gracefully...');
  server.close(() => {
    console.log('✅ Server closed');
    process.exit(0);
  });

  setTimeout(() => {
    console.error('❌ Could not close connections in time');
    process.exit(1);
  }, config.gracefulShutdown.timeoutMs);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = app;
```

