// Simple application for agent to work on with hardcoded values externalized
// This version uses environment variables for all configuration

require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

// =============================================================================
// ENVIRONMENT VARIABLE CONFIGURATION
// =============================================================================

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV'];
requiredEnvVars.forEach(varName => {
  if (!process.env[varName]) {
    console.error(`Missing required environment variable: ${varName}`);
    process.exit(1);
  }
});

// Application Configuration
const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = parseInt(process.env.PORT || '3000', 10);
const HOST = process.env.HOST || '0.0.0.0';
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';

// Security Configuration
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10);
const RATE_LIMIT_MAX_REQUESTS = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100', 10);
const REQUEST_TIMEOUT = parseInt(process.env.REQUEST_TIMEOUT || '30000', 10);

// Data Configuration
const USE_MOCK_DATA = process.env.USE_MOCK_DATA === 'true' || NODE_ENV !== 'production';
const MOCK_USERS = JSON.parse(process.env.MOCK_USERS || JSON.stringify([
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
]));

// Log configuration on startup
if (NODE_ENV !== 'production') {
  console.log('=== APPLICATION CONFIGURATION ===');
  console.log(`NODE_ENV: ${NODE_ENV}`);
  console.log(`PORT: ${PORT}`);
  console.log(`HOST: ${HOST}`);
  console.log(`LOG_LEVEL: ${LOG_LEVEL}`);
  console.log(`USE_MOCK_DATA: ${USE_MOCK_DATA}`);
  console.log(`ALLOWED_ORIGINS: ${ALLOWED_ORIGINS.join(', ')}`);
  console.log(`RATE_LIMIT: ${RATE_LIMIT_MAX_REQUESTS} requests per ${RATE_LIMIT_WINDOW_MS}ms`);
  console.log('==================================\n');
}

// =============================================================================
// EXPRESS APP SETUP
// =============================================================================

const app = express();

// Security middleware
app.use(helmet());

// CORS configuration
app.use(cors({
  origin: ALLOWED_ORIGINS.map(origin => origin.trim()),
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX_REQUESTS,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Request timeout
app.use((req, res, next) => {
  req.setTimeout(REQUEST_TIMEOUT);
  next();
});

// Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);
  next();
});

// =============================================================================
// ROUTES
// =============================================================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    uptime: process.uptime()
  });
});

app.get('/users', (req, res) => {
  if (!USE_MOCK_DATA) {
    // In production, this would query a database
    return res.status(501).json({
      error: 'Database backend not implemented',
      message: 'Set USE_MOCK_DATA=true to use mock data'
    });
  }

  // Return mock users from environment configuration
  res.json(MOCK_USERS);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Error handling middleware
app.use((err, req, res, next) => {
  const timestamp = new Date().toISOString();
  console.error(`[${timestamp}] Error:`, err.message);

  if (NODE_ENV !== 'production') {
    console.error(err.stack);
  }

  res.status(err.status || 500).json({
    error: NODE_ENV === 'production' ? 'Internal Server Error' : err.message,
    ...(NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// =============================================================================
// SERVER STARTUP
// =============================================================================

const server = app.listen(PORT, HOST, () => {
  console.log(`✓ Server running on http://${HOST}:${PORT}`);
  console.log(`✓ Environment: ${NODE_ENV}`);
  console.log(`✓ Press Ctrl+C to stop\n`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('\nSIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('\nSIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

