  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Hardcoded Values Remediation Guide

## Overview
This guide explains how to replace hardcoded values in `app.js` with environment variables and configuration management.

---

## Hardcoded Values Found

### 1. Port Number (3000)

**Original Code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Fixed Code:**
```javascript
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});
```

**Environment Variables:**
```bash
PORT=3000
HOST=0.0.0.0
```

**Usage Examples:**
```bash
# Development (default)
npm start

# Custom port
PORT=8080 npm start

# Docker/Container
PORT=3000 HOST=0.0.0.0 npm start

# Production
NODE_ENV=production PORT=8080 npm start
```

---

### 2. Mock User Data

**Original Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Option A: Configuration-Based (Simple)**
```javascript
// Load from environment variable
const USERS = process.env.USERS_DATA 
  ? JSON.parse(process.env.USERS_DATA)
  : [];

app.get('/users', (req, res) => {
  res.json(USERS);
});
```

**Environment Variable:**
```bash
USERS_DATA=[{"id":1,"name":"Alice","email":"alice@example.com"},{"id":2,"name":"Bob","email":"bob@example.com"}]
```

**Option B: Configuration File (Recommended)**
Create `config/users.json`:
```json
[
  { "id": 1, "name": "Alice", "email": "alice@example.com" },
  { "id": 2, "name": "Bob", "email": "bob@example.com" }
]
```

Code:
```javascript
const fs = require('fs');
const path = require('path');

const usersFilePath = process.env.USERS_CONFIG 
  ? path.resolve(process.env.USERS_CONFIG)
  : path.join(__dirname, 'config/users.json');

const USERS = JSON.parse(fs.readFileSync(usersFilePath, 'utf8'));

app.get('/users', (req, res) => {
  res.json(USERS);
});
```

**Option C: Database Query (Best Practice)**
```javascript
const db = require('./database');

app.get('/users', async (req, res) => {
  try {
    const users = await db.query('SELECT id, name, email FROM users');
    res.json(users);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});
```

---

### 3. Node Environment

**Original Code:**
```javascript
// NODE_ENV not explicitly set
```

**Fixed Code:**
```javascript
const NODE_ENV = process.env.NODE_ENV || 'development';

if (NODE_ENV === 'production') {
  // Production-specific configuration
} else if (NODE_ENV === 'development') {
  // Development-specific configuration
}
```

**Usage:**
```bash
# Development (default)
npm start

# Production
NODE_ENV=production npm start

# Testing
NODE_ENV=test npm test
```

---

### 4. Status Message and Metadata

**Original Code:**
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Fixed Code:**
```javascript
const pkg = require('./package.json');

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    version: pkg.version,
    environment: NODE_ENV,
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    // Add other health metrics
  });
});
```

