    .normalizeEmail()
    .withMessage('Invalid email format'),
  body('age')
    .optional()
    .isInt({ min: 0, max: 150 })
    .withMessage('Age must be between 0 and 150'),
  validateRequest
];

module.exports = {
  validateRequest,
  userIdValidator,
  createUserValidator
};
