  // JWT secret validation (only in production)
  if (config.app.nodeEnv === 'production' && !config.security.jwtSecret) {
    errors.push('JWT_SECRET must be set in production');
  }

  // Rate limit validation
  if (config.rateLimit.maxRequests < 1) {
    errors.push('RATE_LIMIT_MAX_REQUESTS must be at least 1');
  }

  if (errors.length > 0) {
    console.error('Configuration validation errors:');
    errors.forEach((err, i) => console.error(`  ${i + 1}. ${err}`));
    if (config.app.nodeEnv === 'production') {
      process.exit(1);
    }
  }

  return true;
}

validateConfig();

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logDir = config.logging.dir;

// Ensure log directory exists
const fs = require('fs');
if (!fs.existsSync(logDir)) {
  fs.mkdirSync(logDir, { recursive: true });
}

const logger = winston.createLogger({
  level: config.logging.level,
  format: winston.format.combine(
    winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { 
    service: config.app.serviceName,
    environment: config.app.nodeEnv
  },
  transports: [
    new winston.transports.File({ 
      filename: path.join(logDir, config.logging.errorFile), 
      level: 'error',
      maxsize: parseInt(process.env.LOG_MAX_SIZE || '5242880', 10), // 5MB
      maxFiles: parseInt(process.env.LOG_MAX_FILES || '5', 10)
    }),
    new winston.transports.File({ 
      filename: path.join(logDir, config.logging.combinedFile),
      maxsize: parseInt(process.env.LOG_MAX_SIZE || '5242880', 10),
      maxFiles: parseInt(process.env.LOG_MAX_FILES || '5', 10)
    })
  ]
});

// Console logging for non-production
if (config.app.nodeEnv !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    )
  }));
}

// ============================================================================
// APPLICATION SETUP
// ============================================================================

const app = express();

// Security middleware
app.use(helmet()); // Security headers

// CORS - Use configuration
app.use(cors({
  origin: config.cors.origins,
  credentials: config.cors.credentials,
  methods: config.cors.methods,
  allowedHeaders: config.cors.allowedHeaders,
  maxAge: config.cors.maxAge
}));

// Body parser with configurable limits
app.use(express.json({ 
  limit: config.bodyParser.jsonLimit 
}));

app.use(express.urlencoded({ 
  limit: config.bodyParser.urlencodedLimit,
  extended: config.bodyParser.extended 
}));

// Rate limiting - Use configuration
const limiter = rateLimit({
  windowMs: config.rateLimit.windowMs,
  max: config.rateLimit.maxRequests,
  message: config.rateLimit.message,
  standardHeaders: true,
  legacyHeaders: false
});

app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent')
    });
  });
  next();
});

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: config.app.nodeEnv
  });
});

// Example API endpoint
app.get('/users', (req, res) => {
  logger.warn('Unprotected /users endpoint accessed', {
    ip: req.ip,
    userAgent: req.get('user-agent')
  });

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Configuration endpoint (development only)
if (config.app.nodeEnv === 'development') {
  app.get('/config', (req, res) => {
    // Return config without sensitive values
    const safeConfig = {
      app: config.app,
      cors: {
        origins: config.cors.origins,
        methods: config.cors.methods,
        credentials: config.cors.credentials
      },
      rateLimit: {
        windowMs: config.rateLimit.windowMs,
        maxRequests: config.rateLimit.maxRequests
      },
      logging: config.logging
    };
    res.json(safeConfig);
  });
}

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  logger.warn('404 Not Found', {
    path: req.path,
    method: req.method
  });
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    status: err.status
  });

  const message = config.app.nodeEnv === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(err.status || 500).json({
    error: message
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(config.app.port, config.app.host, () => {
  logger.info(
    `Server running on ${config.app.host}:${config.app.port} ` +
    `in ${config.app.nodeEnv} mode`
  );

  // Log configuration on startup (non-sensitive values)
  if (config.app.nodeEnv === 'development') {
    logger.debug('Configuration loaded', {
      port: config.app.port,
      host: config.app.host,
      corsOrigins: config.cors.origins.length,
      rateLimitMax: config.rateLimit.maxRequests,
      logLevel: config.logging.level
    });
  }
});

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

// ============================================================================
// EXPORTS
// ============================================================================

module.exports = { app, config, logger };

// config/validator.js - Configuration validation utility

const Joi = require('joi');

/**
 * Schema for all environment variables
 * Defines validation rules and documentation
 */
const configSchema = Joi.object().keys({
  // ========== Application ==========
  NODE_ENV: Joi.string()
    .valid('development', 'staging', 'production', 'test')
    .default('development')
    .description('Application environment'),

  PORT: Joi.number()
    .port()
    .default(3000)
    .description('Server port'),

  HOST: Joi.string()
    .hostname()
    .default('localhost')
    .description('Server host'),

  SERVICE_NAME: Joi.string()
    .default('api')
    .description('Service name for logging'),

  // ========== CORS ==========
  ALLOWED_ORIGINS: Joi.string()
    .default('http://localhost:3000')
    .description('Comma-separated list of allowed origins'),

  CORS_METHODS: Joi.string()
    .default('GET,POST,PUT,DELETE,OPTIONS')
    .description('Comma-separated list of allowed HTTP methods'),

  CORS_ALLOWED_HEADERS: Joi.string()
    .default('Content-Type,Authorization')
    .description('Comma-separated list of allowed headers'),

  CORS_CREDENTIALS: Joi.boolean()
    .default(true)
    .description('Allow credentials in CORS requests'),

  CORS_MAX_AGE: Joi.number()
    .default(86400)
    .description('CORS cache time in seconds'),

  // ========== Rate Limiting ==========
  RATE_LIMIT_WINDOW_MS: Joi.number()
    .default(900000)
    .description('Rate limit time window in milliseconds'),

  RATE_LIMIT_MAX_REQUESTS: Joi.number()
    .min(1)
    .default(100)
    .description('Maximum requests per time window'),

  RATE_LIMIT_MESSAGE: Joi.string()
    .default('Too many requests from this IP, please try again later.')
    .description('Rate limit error message'),

  // ========== Body Parser ==========
  BODY_LIMIT_JSON: Joi.string()
    .default('10mb')
    .description('Maximum JSON payload size'),

  BODY_LIMIT_URLENCODED: Joi.string()
    .default('10mb')
    .description('Maximum URL-encoded payload size'),

  EXPRESS_EXTENDED_URLENCODED: Joi.boolean()
    .default(true)
    .description('Parse extended URL-encoded bodies'),

  // ========== Logging ==========
  LOG_LEVEL: Joi.string()
    .valid('error', 'warn', 'info', 'http', 'debug', 'verbose', 'silly')
    .default('info')
    .description('Log level'),

  LOG_DIR: Joi.string()
    .default('./logs')
    .description('Log directory'),

  ERROR_LOG_FILE: Joi.string()
    .default('error.log')
    .description('Error log filename'),

  COMBINED_LOG_FILE: Joi.string()
    .default('combined.log')
    .description('Combined log filename'),

  LOG_MAX_SIZE: Joi.number()
    .default(5242880)
    .description('Maximum log file size in bytes'),

  LOG_MAX_FILES: Joi.number()
    .default(5)
    .description('Maximum number of log files to keep'),

  // ========== Security ==========
  JWT_SECRET: Joi.string()
    .when('NODE_ENV', {
      is: 'production',
      then: Joi.required()
        .description('JWT secret key (REQUIRED in production)'),
      otherwise: Joi.string()
        .default('dev-secret-key')
        .description('JWT secret key')
    }),

  JWT_EXPIRATION: Joi.string()
    .default('24h')
    .description('JWT expiration time'),

  BCRYPT_ROUNDS: Joi.number()
    .default(10)
    .min(4)
    .max(15)
    .description('Bcrypt hashing rounds'),

  // ========== Database (Optional) ==========
  DATABASE_URL: Joi.string()
    .uri()
    .description('Database connection URL'),

  DATABASE_POOL_SIZE: Joi.number()
    .default(10)
    .description('Database connection pool size'),

  DATABASE_POOL_IDLE_TIMEOUT: Joi.number()
    .default(30000)
    .description('Database connection pool idle timeout'),

  // ========== Redis (Optional) ==========
  REDIS_URL: Joi.string()
    .uri()
    .description('Redis connection URL'),

  REDIS_PASSWORD: Joi.string()
    .description('Redis password'),

  // ========== API Keys (Optional) ==========
  AWS_ACCESS_KEY_ID: Joi.string()
    .description('AWS access key'),

  AWS_SECRET_ACCESS_KEY: Joi.string()
    .description('AWS secret key'),

  STRIPE_SECRET_KEY: Joi.string()
    .description('Stripe API secret key'),

  ANTHROPIC_API_KEY: Joi.string()
    .description('Anthropic API key')
}).unknown(true); // Allow unknown variables

/**
 * Validate and parse environment variables
 * @returns {Object} Validated configuration object
 * @throws {Error} If validation fails in production
 */
function validateConfig() {
  const { error, value } = configSchema.validate(process.env, {
    convert: true, // Convert types if possible
    stripUnknown: false // Keep unknown variables
  });

  if (error) {
    const errorDetails = error.details.map(detail => ({
      key: detail.context.key,
      message: detail.message,
      current: process.env[detail.context.key] || 'not set'
    }));

    console.error('\n❌ Configuration Validation Errors:\n');
    errorDetails.forEach(detail => {
      console.error(`  ${detail.key}:`);
      console.error(`    Error: ${detail.message}`);
      console.error(`    Current: ${detail.current}`);
    });

    if (process.env.NODE_ENV === 'production') {
      console.error('\n⚠️  Configuration validation failed in production!');
      process.exit(1);
    } else {
      console.warn('\n⚠️  Configuration validation failed in development.');
      console.warn('    Continuing with defaults...\n');
    }
  }

  return value;
}

/**
 * Get configuration documentation
 * @returns {String} Formatted configuration documentation
 */
function getConfigDocumentation() {
  const lines = [];

  lines.push('\n📋 Configuration Variables Documentation\n');
  lines.push('═'.repeat(60));

  const schema = configSchema.describe();
  const keys = Object.keys(schema.keys);

  keys.forEach(key => {
    const field = schema.keys[key];
    lines.push(`\n${key}:`);

    if (field.description) {
      lines.push(`  Description: ${field.description}`);
    }

    if (field.default !== undefined) {
      lines.push(`  Default: ${field.default}`);
    }

    if (field.valid) {
      lines.push(`  Valid values: ${field.valid.join(', ')}`);
    }

    if (field.type) {
      lines.push(`  Type: ${field.type}`);
    }
  });

  lines.push('\n' + '═'.repeat(60) + '\n');

  return lines.join('\n');
}

/**
 * Create configuration object from validated env vars
 * @param {Object} validatedEnv - Validated environment variables
 * @returns {Object} Structured configuration object
 */
function buildConfig(validatedEnv) {
  return {
    app: {
      port: validatedEnv.PORT,
      host: validatedEnv.HOST,
      nodeEnv: validatedEnv.NODE_ENV,
      serviceName: validatedEnv.SERVICE_NAME,
      isProduction: validatedEnv.NODE_ENV === 'production',
      isDevelopment: validatedEnv.NODE_ENV === 'development'
    },

    cors: {
      origins: validatedEnv.ALLOWED_ORIGINS.split(',').map(o => o.trim()),
      methods: validatedEnv.CORS_METHODS.split(',').map(m => m.trim()),
      allowedHeaders: validatedEnv.CORS_ALLOWED_HEADERS.split(',').map(h => h.trim()),
      credentials: validatedEnv.CORS_CREDENTIALS,
      maxAge: validatedEnv.CORS_MAX_AGE
    },

    rateLimit: {
      windowMs: validatedEnv.RATE_LIMIT_WINDOW_MS,
      maxRequests: validatedEnv.RATE_LIMIT_MAX_REQUESTS,
      message: validatedEnv.RATE_LIMIT_MESSAGE
    },

    bodyParser: {
      jsonLimit: validatedEnv.BODY_LIMIT_JSON,
      urlencodedLimit: validatedEnv.BODY_LIMIT_URLENCODED,
      extended: validatedEnv.EXPRESS_EXTENDED_URLENCODED
    },

    logging: {
      level: validatedEnv.LOG_LEVEL,
      dir: validatedEnv.LOG_DIR,
      errorFile: validatedEnv.ERROR_LOG_FILE,
      combinedFile: validatedEnv.COMBINED_LOG_FILE,
      maxSize: validatedEnv.LOG_MAX_SIZE,
      maxFiles: validatedEnv.LOG_MAX_FILES
    },

    security: {
      jwtSecret: validatedEnv.JWT_SECRET,
      jwtExpiration: validatedEnv.JWT_EXPIRATION,
      bcryptRounds: validatedEnv.BCRYPT_ROUNDS
    },

    database: validatedEnv.DATABASE_URL ? {
      url: validatedEnv.DATABASE_URL,
      poolSize: validatedEnv.DATABASE_POOL_SIZE,
      poolIdleTimeout: validatedEnv.DATABASE_POOL_IDLE_TIMEOUT
    } : null,

    redis: validatedEnv.REDIS_URL ? {
      url: validatedEnv.REDIS_URL,
      password: validatedEnv.REDIS_PASSWORD
    } : null
  };
}

module.exports = {
  configSchema,
  validateConfig,
  getConfigDocumentation,
  buildConfig
};

